// Referências de boas práticas para a evolução das skills: resumos em português (com palavras próprias) de skills
// públicas com licença MIT do diretório skills.sh. Os revisores usam isto para apontar o que falta numa skill, e o
// especialista usa ao reescrever. Os avisos de licença estão em LICENCAS-TERCEIROS.md. Escrito em 10/11/2026.
import type { EspecialistaIA, SkillEspecialista } from "./especialistas";

export interface Referencia { id: string; titulo: string; fonte: string; caminho: string; resumo: string }

export const REFERENCIAS: Referencia[] = [
  { id: "copywriting", titulo: "Redação persuasiva para páginas", fonte: "coreyhaines31/marketingskills", caminho: "skills/copywriting/SKILL.md",
    resumo: "Antes de escrever, definir a única ação que o visitante deve tomar, quem é o cliente, que dor ele tem, que objeções levanta, de onde vem o tráfego e o que ele já sabe ao chegar; diagnosticar o pedido: (A) texto em branco ou genérico, em que se monta o argumento a partir dos fatos, (B) rascunho com voz própria, em que se preservam vocabulário, ênfase e ângulo do autor, ou (C) ajuste pontual, em que só se mexe no trecho pedido; dividir a página em blocos (título, subtítulo, botão, seções, provas), fazer duas ou três versões de cada, ficar com a melhor e travar; filtro das três perguntas para cada frase: o leitor consegue visualizar? dá para provar se é verdade? um concorrente poderia assinar a mesma frase (teste da troca)?; clareza vence esperteza; benefício acima de característica; números e prazos concretos ('de 4 horas para 15 minutos'); usar as palavras do cliente, tiradas de avaliações, conversas de WhatsApp e atendimento; uma ideia por seção; nunca inventar dados, clientes ou depoimentos: quando faltar prova, dizer qual evidência liberaria a afirmação; topo da página como transformação (desconforto atual → cenário melhor → caminho) e teste do 'Agora você pode...'; botão com verbo + o que a pessoa recebe ('Quero meu orçamento' em vez de 'Enviar'); só um ou dois momentos de impacto por página; evitar vícios de texto de IA: 'não é X, é Y', listas de negações, frases arrastadas em vírgulas, perguntas que a própria marca responde, chavões e travessões em textos curtos; antes de entregar, desfazer toda mudança que não seja claramente melhor." },
  { id: "copy-editing", titulo: "Revisão e edição de textos", fonte: "coreyhaines31/marketingskills", caminho: "skills/copy-editing/SKILL.md",
    resumo: "Escolher o modo antes de revisar: texto genérico (reconstruir a partir dos fatos), texto com voz própria (restaurar sem trocar o argumento) ou ajuste pontual (mexer só no que foi pedido e devolver apenas as linhas alteradas, cada uma com o motivo); método das Sete Varreduras, uma dimensão por vez, voltando às anteriores depois de cada uma: 1) clareza, 2) voz e tom, 3) 'e daí?' (toda característica precisa virar benefício, com a ponte 'o que significa que...'), 4) prove (depoimento com nome, números, casos, garantias), 5) especificidade (números, prazos, exemplos; o que não fica concreto costuma ser enchimento), 6) emoção (pintar o 'antes', micro-histórias, sem manipular) e 7) risco zero (objeções respondidas perto do botão, garantia, próximo passo claro, nada escondido em letras miúdas); regra do Um (uma ideia por seção) e regra do Você (falar com o leitor); em textos importantes, banca de 3 a 5 avaliadores (redator, especialista em usabilidade, cliente cético, estrategista de marca) com nota de 1 a 10, revisando até todos darem 7 ou mais e a média passar de 8; cortar intensificadores e muletas ('muito', 'realmente', 'basicamente'), voz passiva e substantivo no lugar de verbo ('tomar uma decisão' → 'decidir'); frases de até umas 25 palavras e parágrafos de 2 a 4 frases; trocar palavras vagas ('inovador', 'robusto') pelo fato que elas escondem; tirar vícios de texto de IA; páginas antigas envelhecem e pedem revisão periódica; o autor dá a palavra final." },
  { id: "content-strategy", titulo: "Estratégia de conteúdo", fonte: "coreyhaines31/marketingskills", caminho: "skills/content-strategy/SKILL.md",
    resumo: "Todo conteúdo deve ser encontrável na busca, compartilhável ou as duas coisas, com prioridade para a busca, que acumula resultado; tratar cada peça como um lançamento: planejar, publicar e divulgar; pesquisar antes de pautar: perguntas feitas antes da compra, objeções nas vendas, dúvidas repetidas no atendimento e no WhatsApp, linguagem do cliente e lacunas dos concorrentes; filtro do ganho de informação: ler os primeiros resultados do Google e escrever uma frase sobre o que a peça traz a mais (dado próprio, exemplo real, modelo pronto, opinião mais firme); sem essa frase, não produzir; 3 a 5 pilares temáticos ligados ao que a empresa vende, cada um com um conteúdo central e subtemas interligados; mapear temas por etapa da jornada: descoberta ('o que é', 'como fazer'), comparação ('melhor', 'x ou y'), decisão ('preço', 'avaliações') e uso ('modelo', 'passo a passo'); fórmula público + uso ('controle de estoque para padaria'); priorizar ideias com nota ponderada: impacto no cliente 40%, aderência ao produto 30%, potencial de busca 20%, esforço 10%; calendário 60/30/10 (busca, compartilhável, experimental); listas de estatísticas e calculadoras tendem a ganhar mais citações; escrever 10 títulos antes de escolher e revisar em várias passadas; criar uma peça forte e redistribuir em vários canais, pensando nos trechos reaproveitáveis; modelo ORB: público emprestado (parcerias, participações) → alugado (redes sociais) → próprio (lista de e-mail, site, comunidade), levando sempre para o próprio; erros: postar em tudo sem peça principal e depender só do alcance das redes." },
  { id: "marketing-psychology", titulo: "Psicologia aplicada ao marketing", fonte: "coreyhaines31/marketingskills", caminho: "skills/marketing-psychology/SKILL.md",
    resumo: "Partir do comportamento que se quer provocar, do que o cliente já acredita e do que hoje impede a ação; modelos de raciocínio: primeiros princípios e 5 porquês, inversão (listar o que faria a campanha fracassar e prevenir), Pareto 80/20, teoria das restrições (achar o gargalo antes de otimizar o resto), custo de oportunidade, pensamento de segunda ordem (promoção relâmpago ensina o cliente a esperar desconto), mapa não é território; Trabalhos a Serem Feitos (JTBD): o cliente 'contrata' o produto para obter um resultado; vieses úteis: prova social, mera exposição, aversão à perda, ancoragem, enquadramento, efeito isca, paradoxo da escolha (três opções com uma recomendada), opção já marcada, gradiente de meta e efeito Zeigarnik (barra de progresso, tarefa incompleta), regra do pico e do fim (caprichar no momento alto e no encerramento), efeito IKEA, efeito do grátis, reciprocidade (dar valor antes de pedir), compromisso e coerência (pedido pequeno primeiro), autoridade, afinidade; preço: final 9 para valor e número redondo para premium, regra do 100 (abaixo de R$ 100 desconto em %, acima em reais), valor por dia ou por parcela muda a percepção; modelos de ação: AIDA, Fogg (motivação × capacidade × gatilho), EAST (fácil, atraente, social, oportuno), COM-B e lei de Hick (menos campos, um botão); erros: culpar o cliente em vez do processo, insistir por custo afundado, copiar só casos de sucesso (viés de sobrevivência); escassez e urgência só quando forem reais, e validar com clientes de verdade." },
  { id: "video", titulo: "Produção de vídeos de marketing", fonte: "coreyhaines31/marketingskills", caminho: "skills/video/SKILL.md",
    resumo: "Começar pela estratégia, não pela ferramenta: definir o tipo (demonstração, explicativo, depoimento, corte para redes, anúncio, tutorial), a plataforma, a duração e se é peça única ou modelo repetível; escolher a abordagem certa: gravação de tela para mostrar o produto real, vídeo montado por código ou modelo editável para conteúdo recorrente e em série, geração por IA para cenas de apoio impossíveis de filmar, apresentador virtual para conteúdo recorrente ou em vários idiomas e corte de conteúdo longo (live, entrevista) em vários clipes curtos; conteúdo autêntico do dono deve ser gravado por ele mesmo; prompt de vídeo com sujeito + ação + câmera + estilo + clima, deixando claro o movimento de câmera; IA não escreve texto legível na cena, então textos entram por sobreposição na edição; IA também não serve para mostrar produto, marca ou lugar real específico, porque inventa detalhes; legenda sempre, já que a maior parte do vídeo em redes é vista sem som; proporção certa: 9:16 para Reels, TikTok e Shorts, 16:9 para YouTube e site, 1:1 ou 4:5 para feed; roteiro explicativo em problema → solução → chamada para ação, com o gancho escrito primeiro e a recompensa logo no começo; para imitar um estilo de edição, decompor a referência em uma tabela de batidas (ritmo de cortes, legendas, zooms, som) e copiar só a linguagem, nunca imagens, roteiro ou música; voz clonada só com consentimento do dono da voz; revisar quadros-chave antes de publicar (texto cortado, letra pequena); evitar produção exagerada: no TikTok o autêntico costuma render mais." },
  { id: "image", titulo: "Imagens de marketing", fonte: "coreyhaines31/marketingskills", caminho: "skills/image/SKILL.md",
    resumo: "Definir o tipo de imagem (capa de artigo, post, banner, maquete de produto, peça de marca), onde ela vai aparecer e as medidas exatas antes de produzir; escolher a abordagem: geração por IA para capas e cenas únicas, modelo de design para peças recorrentes e fiéis à marca, captura de tela real para mostrar sistema ou aplicativo, banco de imagens quando a pressa vale mais que a originalidade; prompt com sujeito + ambiente + estilo + luz + composição + formato; informar sempre a proporção e o estilo ('foto realista', 'ilustração plana', '3D'); IA erra textos longos e inventa telas de sistema: no máximo um título curto, o resto entra por sobreposição; logotipo e ícone do site devem ser desenhados, não gerados; medidas de referência: feed do Instagram 1080×1080 ou 1080×1350, Stories 1080×1920, prévia de link 1200×630; banners com pouco texto e o essencial no centro, conferidos no tamanho real do celular e trocados quando envelhecerem; manter cores, fontes e posição do logotipo iguais em todas as peças; otimizar para o site: WebP como padrão, redimensionar ao tamanho exibido, compressão de 75 a 85% em fotos, capa abaixo de uns 200 KB, carregamento tardio para o que fica abaixo da dobra, largura e altura declaradas e texto alternativo descritivo; toda página precisa de imagem de prévia para quando o link for compartilhado no WhatsApp e nas redes; erros comuns: imagem pesada deixando o site lento, link sem prévia, proporção errada, falta de direção de estilo e visual inconsistente entre as peças." },
  { id: "emails", titulo: "Sequências de e-mail", fonte: "coreyhaines31/marketingskills", caminho: "skills/emails/SKILL.md",
    resumo: "Antes de montar a sequência, definir o tipo (boas-vindas, nutrição de contatos, reengajamento, pós-compra, evento, educativa, vendas), o gatilho de entrada, o que o contato já sabe, a meta principal, o que conta como sucesso e as condições de saída; princípios: um e-mail, uma tarefa e um botão principal; valor antes do pedido; relevância acima de volume, com segmentação; todo e-mail leva a um próximo passo claro; referências: boas-vindas com 5 a 7 e-mails em cerca de duas semanas (entrega do prometido, vitória rápida, história, prova social, objeção, destaque, oferta); nutrição com 6 a 8 em 2 a 3 semanas terminando em oferta direta; reengajamento com 3 ou 4 após 30 a 60 dias parado (contato sincero, novidades, incentivo, última chance de ficar ou sair); primeiro envio imediato, depois intervalos de 1 a 2 dias, espaçando com o tempo; venda entre empresas evita fim de semana, venda ao consumidor testa; assunto claro e específico, de 40 a 60 caracteres, com texto de prévia que complete a ideia sem repetir; estrutura: abertura que prende, contexto, conteúdo útil, chamada para ação e despedida humana; parágrafos curtos e leitura pensada para o celular; transacional de 50 a 125 palavras, educativo de 150 a 300, história de 300 a 500; tom de conversa, lido em voz alta; evitar 'Re:' ou 'Enc:' falsos, iscas sensacionalistas, 'espero que esteja bem', 'qualquer dúvida estou à disposição' e vícios de texto de IA; acompanhar os números e comparar com metas." },
  { id: "ad-creative", titulo: "Criativos de anúncios", fonte: "coreyhaines31/marketingskills", caminho: "skills/ad-creative/SKILL.md",
    resumo: "Levantar plataforma, formato, oferta, diferencial, público, nível de consciência (conhece o problema, a solução ou o produto) e restrições da marca e das políticas da plataforma; ancorar tudo em material real: anúncios vencedores dos últimos 90 dias, 50 a 100 avaliações de clientes e comentários dos anúncios, que mostram objeções e elogios espontâneos; cada conceito diz de onde veio, sem inventar números, resultados ou depoimentos; definir 3 a 5 ângulos com motivações diferentes (dor, resultado, prova social, curiosidade, comparação, urgência real, identidade, contrário ao senso comum) e variar estrutura e tom, não só palavras; conferir limites de caracteres antes de entregar: no Google, títulos de 30 e descrições de 90, que precisam fazer sentido sozinhos e em qualquer combinação (incluir título com a palavra-chave, com benefício e com chamada para ação); na Meta, gancho nos primeiros 125 caracteres e título de uns 40; no TikTok, texto de até uns 80; descrição complementa o título sem repetir; ao iterar, estudar vencedores e perdedores (temas, estruturas, palavras, tamanho), reforçar o que funciona, testar 1 ou 2 ângulos novos e registrar cada rodada; hipótese de teste que pode perder: métrica, comparação, público e direção esperada; mudar uma variável por vez e esperar ao menos mil impressões antes de julgar; gerar muitas opções para escolher poucas; evitar ganchos genéricos ('pare de rolar'), chamadas vagas ('comece hoje'), negações empilhadas e vícios de IA; em vídeo vertical, texto dentro da área segura; não simular conversas ou depoimentos que pareçam reais." },
  { id: "ads", titulo: "Anúncios pagos", fonte: "coreyhaines31/marketingskills", caminho: "skills/ads/SKILL.md",
    resumo: "Definir antes de gastar: um objetivo por campanha (alcance, tráfego, contatos ou vendas), custo por aquisição (CPA) ou retorno sobre o gasto (ROAS) desejado, verba e página de destino; não lançar sem conversão testada com um caso real; escolher o canal pela intenção: busca no Google para quem já procura, Meta e TikTok para gerar demanda com bom criativo; nomes de campanha padronizados (plataforma_objetivo_público_oferta_data); em teste, cerca de 70% da verba no que já funciona e 30% em novidades; ao escalar, aumentos de até 20% com 3 a 5 dias de intervalo; o conhecimento do público rende mais no criativo (gancho, título, palavras do cliente) do que em filtros empilhados, salvo na busca, onde a palavra-chave decide; ordem de teste: conceito, gancho, visual, texto, chamada; remarketing (anúncios para quem já visitou) por etapa do funil, com janela e limite de frequência, sem quem já comprou e trocando a oferta (outro produto, diagnóstico grátis, depoimentos, objeções respondidas); ligar para quem não fechou e usar as objeções reais nos anúncios; separar busca pelo nome da marca do resto: reportar o total, otimizar pelo que não é marca; achar o CPA máximo que ainda dá lucro e escalar até perto dele, olhando o caixa líquido e não só o ROAS; revisão semanal na ordem gasto, tráfego, conversões, criativo, página, rastreamento, fechando com uma decisão (manter, corrigir, testar ou investigar); nunca somar conversões de janelas diferentes; dado ausente é marcado como ausente, não estimado; mudança em conta ativa só com proposta, efeito esperado e forma de desfazer." },
  { id: "analytics", titulo: "Plano de medição e análise", fonte: "coreyhaines31/marketingskills", caminho: "skills/analytics/SKILL.md",
    resumo: "Medir para decidir: cada evento responde a uma pergunta de negócio; partir das decisões e chegar aos dados, evitando métricas de vaidade; manter um plano de rastreamento em tabela (evento, categoria, propriedades, gatilho, notas) sempre documentado; nomes no padrão objeto_ação, minúsculos, com sublinhado e específicos, deixando o contexto nas propriedades; quando a ferramenta tiver eventos recomendados, usar o nome dela e mapear o nome interno; parâmetros UTM sempre em minúsculas, com um único separador e uma grafia por origem guardada em planilha comum, sem dados pessoais, testando o link final depois de encurtadores; padrão fixo por tipo de parceiro (boletim por e-mail, criador, podcast, afiliado, comunidade), um link por inserção e um agrupamento de canais próprio para esse tráfego não cair em 'não atribuído'; onde não há link clicável, usar cupom ou endereço curto; visitas vindas de assistentes de IA aparecem só em parte, então o número é um piso; validar antes de confiar: dispara no gatilho certo, valores preenchidos, sem duplicidade, funciona no celular, sem dado pessoal; calcular totais e taxas a partir das linhas, em planilha ou programa, e conferir cada número principal por outro caminho; taxa só com numerador e denominador da mesma janela já fechada (nunca a verba do mês inteiro sobre as conversões de meio mês); coorte ainda em observação é pendente, não fracasso; ao falar de um segmento, usar os números dele; a recomendação final se apoia no objetivo declarado e diz o que cada opção ganha e perde." },
  { id: "ab-testing", titulo: "Testes A/B e experimentos", fonte: "coreyhaines31/marketingskills", caminho: "skills/ab-testing/SKILL.md",
    resumo: "Hipótese escrita antes: porque observamos X, acreditamos que a mudança Y causará Z no público W, medido por M; uma variável por teste, ousada o bastante para ser detectada; tamanho de amostra calculado antes (95% de confiança e 80% de poder; ex.: base de 5% e ganho relativo de 20% pedem cerca de 8.200 visitantes por versão; base de 3% e ganho de 10%, cerca de 53 mil), o que revela quando o tráfego não comporta o teste; métrica principal ligada a valor, secundárias para explicar e de proteção (reclamações, devoluções) que interrompem o teste se piorarem muito; para elementos que só parte do público usa (vídeo, simulador), comparar apenas quem chegou ao ponto de exposição nas duas versões; divisão 50/50 por padrão, 90/10 quando o risco é alto, e a mesma pessoa vê sempre a mesma versão; antes de lançar, conferir hipótese, métrica, amostra, versões e rastreamento; durante, não espiar e parar cedo, não mexer nas versões, não trocar fontes de tráfego; na análise, relatar tamanho do efeito e intervalo de confiança, não só o p-valor (que não é a chance de a versão vencer); resultado neutro não se prolonga até 'dar significativo'; recortes não planejados são exploratórios e pedem novo teste; registrar cada teste (hipótese, telas, amostra, resultado, decisão, aprendizado) num manual de padrões; priorizar a fila com ICE = (Impacto + Confiança + Facilidade) / 3, notas de 1 a 10, revistas todo mês; ritmo saudável: testes de 2 a 4 semanas e taxa de acerto de 20% a 30%." },
  { id: "attribution", titulo: "Atribuição de resultados", fonte: "coreyhaines31/marketingskills", caminho: "skills/attribution/SKILL.md",
    resumo: "Atribuição é indicação, não verdade: todo modelo embute uma opinião; modelos: primeiro toque (todo crédito à descoberta), último toque (ao fechamento), último não direto, linear (partes iguais), decaimento no tempo (mais peso perto da compra), em U (40% primeiro, 40% último, 20% meio) e baseado em dados, que só funciona com volume (cerca de 200 conversões e 2.000 interações em 30 dias); em ciclos longos, mostrar primeiro e último toque lado a lado: a diferença ensina; ser consistente importa mais que o modelo; escolher uma fonte da verdade para contar vendas (o sistema onde o dinheiro entra) e nunca somar o que cada plataforma informa, pois todas reivindicam a mesma venda; confiar em tendências que aparecem em todas as fontes, não em números exatos; perguntar 'como conheceu a gente?' no momento da compra, com lista de opções e campo livre, descontando o viés de memória; com verba pequena, UTM bem feito, último não direto e essa pergunta bastam; testes de incrementalidade (desligar um canal numa região ou período e comparar) resolvem disputas entre canais; modelagem de mix de mídia exige 2 a 3 anos de dados semanais e variação real de verba; pontos cegos: tráfego direto, busca pelo nome da marca, boca a boca e conversas privadas (WhatsApp) e respostas de IA escondem o canal real; com dados próprios, ligar a navegação anônima à conversão quando a pessoa se identifica, sem pôr e-mail em links, e ignorar login e pagamento como origem; relatório: decisão, fonte da verdade, tabela por fonte sem somar, lacunas e recomendação com nível de confiança." },
  { id: "conversion-tracking", titulo: "Rastreamento de conversões", fonte: "coreyhaines31/marketingskills", caminho: "skills/conversion-tracking/SKILL.md",
    resumo: "Separar os dois tipos: contato (formulário, agendamento, chat, clique em telefone ou WhatsApp) e venda online; conversão só no sucesso confirmado: clique no botão conta erros e robôs, e a página de obrigado precisa barrar recarga e acesso direto; código disparado não é conversão recebida, então confirmar no destino; antes de montar, responder três perguntas: o que conta como conversão (talvez o contato qualificado ou a venda fechada), para onde ela vai e qual ferramenta gera o momento; observar antes de perguntar e sempre checar se algo já envia pelo servidor ou por integração nativa, para não contar em dobro; marcar cada achado como observado, relatado ou deduzido; sintoma pede diagnóstico, não mudança: apontar causa e correção e pedir aval; 'não achei a causa' é resposta válida, inventar não; preferir a menor correção reversível; teste real gera conversão real e exige aprovação; priorizar integrações nativas e ativar a correspondência avançada (e-mail e telefone criptografados) antes de pagar por ferramentas; esperar perda de 10% a 30% no navegador; respeitar o consentimento; sinais fracos ficam como secundários e cada contato conta uma vez; diferença de 10% a 30% entre análise e plataforma é normal, acima de 40% ou inversão merece investigação; não julgar os últimos 3 dias; alinhar ação, data, fuso, janela e escopo antes de comparar; em loja, conferir valor com ou sem frete e imposto, moeda, deduplicação por ID do evento e estornos; devolver vendas fechadas às plataformas; entregar com IDs, nomes de eventos e roteiro de reteste de 5 minutos." },
  { id: "social", titulo: "Conteúdo orgânico nas redes", fonte: "coreyhaines31/marketingskills", caminho: "skills/social/SKILL.md",
    resumo: "História e conexão vêm antes da tática; definir objetivo, público, tom de voz e tempo disponível; 3 a 5 pilares de conteúdo com peso (ex.: 30% tendências, 25% bastidores, 25% educativo, 15% pessoal, 5% promoção); a primeira linha decide a leitura: ganchos de curiosidade, história, utilidade ou opinião contrária, sempre preenchidos com fato, número ou caso real; evitar marcas de texto gerado: 'não é X, é Y', listas de negações, perguntas que a própria frase responde, clichês, uma frase por linha no post inteiro, iscas como 'concorda?', vulnerabilidade forçada e emojis como marcadores; reaproveitar conteúdo longo (vídeo, artigo, transmissão) em 5 a 10 trechos autônomos, cada um com texto próprio e legenda na tela, espalhados por 1 a 2 semanas; conteúdo atemporal volta a cada 3 a 6 meses; produzir em lote (2 a 3 h por semana) e deixar espaço para o tempo real; rotina diária de 30 min: responder todos os comentários, comentar com conteúdo em 5 a 10 perfis-alvo, compartilhar com opinião, mandar algumas mensagens; cultivar 20 a 50 perfis do nicho; medir comentários, compartilhamentos, salvamentos, mensagens e cliques, não só curtidas; revisar toda semana os 3 melhores e os 3 piores; alcance caindo: tirar links externos do texto, variar formato e horário; vídeo curto vertical: gancho visual, falado e escrito no 1º segundo, estrutura problema-solução, lista ou tutorial com o resultado no início, legenda de até 2 linhas com 3 a 5 palavras, áudio limpo e chamada no fim; estudar padrões de perfis fortes do nicho e aplicar com voz própria; publicar só depois de aprovação." },
  { id: "community-marketing", titulo: "Marketing de comunidade", fonte: "coreyhaines31/marketingskills", caminho: "skills/community-marketing/SKILL.md",
    resumo: "Base: uma identidade que o membro tem ou quer ter, não o produto; cada ação responde 'o que o membro ganha?' (conhecimento, contatos, reconhecimento, voz no produto); pensar no ciclo: entra, recebe valor, participa, ajuda outros, atrai novos; começar recrutando 20 a 50 fundadores um a um, antes de abrir ao público; escrever regras que descrevam o clima desejado; semear 5 a 10 conversas-modelo; no início, responder tudo e dar boas-vindas pelo nome; definir uma ação semanal central e premiá-la em público; para crescer, achar onde o membro some (entra e não posta, posta uma vez e sai), criar trilha de boas-vindas (mensagem fixada, apresentação, 'comece aqui'), mostrar conquistas dos membros, manter rituais (tópico semanal, sessão mensal de perguntas, desafios) e valorizar os mais ativos com reconhecimento, acesso antecipado e moderação; embaixadores: escolher quem já indica sem pedir, convidar pessoalmente, dar benefícios reais e material pronto, medir as indicações; suporte: base de respostas a partir das dúvidas, selo para quem ajuda, crédito público quando uma sugestão vira mudança, humor acompanhado toda semana; escolher a plataforma pelos prós e contras (grupos de WhatsApp e Facebook, fórum, servidor de chat); saúde: ativos diários sobre mensais acima de 20%, % de novos que postam em 7 dias, % de posts com resposta, inativos há 30 dias, % de conteúdo fora da equipe; alertas: só a empresa posta, dúvidas sem resposta por mais de 24 h, 5 pessoas fazendo 80% da conversa; o papel muda de arquiteto (até 100 membros) a gestor (até 1.000) e facilitador." },
  { id: "customer-research", titulo: "Pesquisa com clientes", fonte: "coreyhaines31/marketingskills", caminho: "skills/customer-research/SKILL.md",
    resumo: "Ordem: analisar o que já existe, garimpar o que clientes dizem em público e só então perguntar; em entrevistas, conversas de venda e avaliações, extrair a tarefa que o cliente quer cumprir (Jobs to Be Done: funcional, emocional e social), dores (pesam mais as espontâneas e emotivas), gatilho da busca, resultado desejado, objeções, alternativas (inclusive não fazer nada) e as palavras exatas; em pesquisas, segmentar antes de concluir e comparar respostas abertas com fechadas; no atendimento, separar defeito, confusão, recurso ausente e expectativa errada; na nota de recomendação (NPS), neutros e detratores ensinam mais; síntese: agrupar temas, pontuar frequência × intensidade, segmentar, separar 5 a 10 frases-chave e apontar contradições entre fala e ação; confiança alta = 3 ou mais fontes independentes, espontâneo e consistente; média = 2 fontes ou só quando perguntado; baixa = fonte única; pesar mais os últimos 12 meses; lembrar vieses (avaliação vem de quem tem opinião forte; atendimento só mostra problema); mínimo de 5 evidências por segmento; fontes: comentários nas redes, grupos de WhatsApp e Facebook, avaliações no Google e em lojas de aplicativo, sites de reclamação; entrevistar os melhores clientes em tom de conversa, tentando refutar a ideia, com 5 porquês até a raiz e 'quem mais devo ouvir?' no fim; mirar 10 conversas e aceitar 5; teste de encaixe produto-mercado: 'como se sentiria se não pudesse mais usar?', meta de 40% 'muito decepcionado'; personas só com dados, sem média entre segmentos, campo vazio quando faltar dado, revistas a cada trimestre." },
  { id: "cro", titulo: "Otimização de conversão de páginas", fonte: "coreyhaines31/marketingskills", caminho: "skills/cro/SKILL.md",
    resumo: "- Antes de opinar, defina o tipo de página, a ação principal esperada (comprar, pedir orçamento, chamar no WhatsApp, cadastrar) e de onde vem o visitante (busca, anúncio, Instagram, e-mail).\n- Avalie na ordem de impacto: proposta de valor, título, botão de ação, hierarquia visual, provas de confiança, objeções e atritos.\n- Teste dos 5 segundos: um visitante novo entende o que é e por que importa? Prefira benefício a característica e a língua do cliente ao jargão da empresa.\n- Título forte: “Consiga [resultado] sem [dor]”, com números, prazos ou detalhes concretos, coerente com o anúncio que trouxe a pessoa.\n- Uma ação principal, visível sem rolar e repetida nos pontos de decisão; texto do botão que diz o ganho (“Quero meu orçamento” em vez de “Enviar”).\n- Provas perto do botão: depoimentos com nome e foto, resultados com números reais, nota e quantidade de avaliações.\n- Responda às objeções (preço, “serve para mim?”, dificuldade, “e se não der certo?”) com perguntas frequentes, garantia e processo explicado.\n- Atritos comuns: campos demais, próximo passo confuso, menu que distrai, página lenta ou ruim no celular.\n- Página de anúncio: uma só ação e argumento completo; página inicial: atender quem já quer comprar e quem ainda pesquisa; página de preços: indicar o plano recomendado.\n- Entregue em blocos: ganhos rápidos, mudanças de alto impacto, hipóteses para teste A/B e 2 ou 3 versões de título e botão com justificativa.\n- Pergunte a taxa atual e a meta, o que acontece depois do clique e o que já foi tentado." },
  { id: "signup", titulo: "Fluxo de cadastro", fonte: "coreyhaines31/marketingskills", caminho: "skills/signup/SKILL.md",
    resumo: "- Mapeie o fluxo: passos, campos obrigatórios, taxa de conclusão e campo onde as pessoas desistem.\n- Cada campo a mais derruba a conclusão. Para cada um: é preciso agora? Dá para pedir depois, aos poucos? Dá para deduzir de outro dado?\n- Essencial costuma ser só e-mail ou celular e senha; empresa, cargo, endereço e preferências ficam para depois.\n- Mostre valor antes de pedir compromisso; em loja virtual, deixe comprar sem cadastro e ofereça criar a conta após o pedido.\n- E-mail num campo só, sem repetir, validado na hora e com sugestão para erro de digitação (“gmial” vira “gmail”).\n- Senha: botão de mostrar, regras visíveis antes do erro, permitir colar, medidor de força; considere entrar por código ou link enviado.\n- Entrar com Google ou Apple bem à vista, separado do formulário de e-mail.\n- Telefone só se necessário, explicando o motivo e formatando com DDD; endereço preenchido pelo CEP.\n- Até 3 campos, um passo só; com mais, vários passos com barra de progresso, perguntas fáceis primeiro, botão de voltar e progresso salvo.\n- Erro mostrado no campo, claro e com saída (“e-mail já cadastrado: entrar ou recuperar senha”); nunca apagar o que foi digitado.\n- Rótulos sempre visíveis; exemplo dentro do campo não substitui rótulo.\n- No celular: botões de 44 px ou mais, teclado certo para cada campo, preenchimento automático e uma coluna.\n- Após enviar: confirmação clara e próximo passo; se houver verificação, permitir reenviar, lembrar do spam e corrigir o e-mail.\n- Meça início, conclusão, abandono e erros por campo, tempo gasto e celular contra computador." },
  { id: "seo-audit", titulo: "Auditoria de SEO", fonte: "coreyhaines31/marketingskills", caminho: "skills/seo-audit/SKILL.md",
    resumo: "- Contexto primeiro: tipo de site, objetivo, temas prioritários, mudanças recentes e tráfego atual.\n- Prioridade: rastreamento e indexação, base técnica, otimização de cada página, qualidade do conteúdo e autoridade (links e menções).\n- Rastreamento: robots.txt sem bloqueio acidental, sitemap só com páginas canônicas e indexáveis, páginas importantes a até 3 cliques da inicial e nenhuma órfã.\n- Indexação: noindex indevido, canônicas erradas, cadeias de redirecionamento, páginas vazias tratadas como válidas e duplicados.\n- Experiência da página (Core Web Vitals): LCP abaixo de 2,5 s, INP abaixo de 200 ms, CLS abaixo de 0,1; imagens leves (WebP) e sob demanda, HTTPS em tudo, celular com o mesmo conteúdo.\n- Título único, termo principal no início, 50 a 60 caracteres e motivo para clicar; descrição de 150 a 160; um H1 por página e subtítulos em ordem.\n- Conteúdo que atende à intenção de busca melhor que o dos concorrentes; um termo principal por página, sem páginas do próprio site disputando entre si.\n- Confiança (E-E-A-T): experiência própria, autor identificado, contato e dados da empresa visíveis.\n- Negócio local: nome, endereço e telefone iguais em todo lugar, Perfil da Empresa no Google completo, avaliações e páginas por bairro ou cidade. Loja virtual: categorias rasas, descrição de produto copiada, produto esgotado mal tratado.\n- Ganho rápido: páginas entre as posições 8 e 20.\n- Erro comum: concluir que não há dados estruturados olhando só o código bruto, quando eles entram por script.\n- Relate cada achado com problema, impacto, evidência, correção e prioridade." },
  { id: "schema", titulo: "Dados estruturados (JSON-LD)", fonte: "coreyhaines31/marketingskills", caminho: "skills/schema/SKILL.md",
    resumo: "- Antes, veja o tipo de página, a marcação existente, os erros no Search Console e o destaque desejado na busca.\n- Precisão acima de tudo: marque só o que está visível na página e atualize sempre que preço, horário ou conteúdo mudarem.\n- Use JSON-LD, no cabeçalho ou no fim da página, seguindo as diretrizes do Google; nada de truques como avaliações inventadas.\n- Tipos mais úteis: empresa (Organization); negócio local (LocalBusiness: nome e endereço, mais telefone, horário e localização); produto (Product: nome, imagem e oferta com preço, moeda BRL e disponibilidade; recomendados marca, código e nota); artigo (Article: título, imagem, data e autor); trilha de navegação (BreadcrumbList); evento (Event: nome, data e local).\n- Vários tipos cabem na mesma página num @graph.\n- Ser válido no vocabulário Schema não garante destaque no Google: confira a lista atual de recursos suportados antes de prometer algo. Segundo o documento, perguntas frequentes (FAQPage) e passo a passo (HowTo) já não geram destaque; ainda descrevem conteúdo visível, mas não servem para aparecer melhor.\n- Falta de relatório para um tipo aposentado não é erro de implementação.\n- Erros comuns: propriedade obrigatória ausente, data fora do padrão ISO 8601, endereço de página incompleto (sem https e domínio), marcação diferente do que a página mostra.\n- Conferência final: recurso suportado ou uso justificado, validação no validador do Schema e no teste de resultados enriquecidos do Google, obrigatórios resolvidos e conteúdo igual ao da página.\n- Em site com modelo, gere a marcação no modelo, não à mão." },
  { id: "onboarding", titulo: "Primeiros passos e ativação", fonte: "coreyhaines31/marketingskills", caminho: "skills/onboarding/SKILL.md",
    resumo: "- Defina o momento de virada: a ação que mostra que o cliente entendeu o valor (primeira compra, primeiro agendamento, primeira aula).\n- Julgue a ativação pela conversão em cliente pagante e pela permanência após 90 dias, não pelo volume de cadastros.\n- Para achá-lo: cadastro como marco zero, uma janela curta de ações iniciais e outra, posterior, para a retenção; turmas recentes sem prazo completo não contam como perdidas; correlação é hipótese a testar.\n- Caminho mínimo até o valor: o menor número de passos; uma meta por primeira sessão; fazer vale mais que ver tutorial.\n- Psicologia útil: progresso concedido (lista que já começa com um item feito); regra do pico e do fim (crie um ponto alto e termine bem); tarefas nem fáceis nem difíceis demais; modelo de Fogg: ação = motivação × capacidade × gatilho, juntos.\n- Some aceleradores (modelos prontos, dados preenchidos, vitórias rápidas) e tire bloqueios (campos obrigatórios, becos sem saída).\n- Lista de tarefas com 3 a 7 itens, ordenada pelo valor, com barra de progresso, comemoração no fim e opção de fechar.\n- Tela vazia explica, mostra exemplo e oferece uma ação; tour de no máximo 3 a 5 passos, pulável e sem repetir.\n- Mensagens por e-mail ou WhatsApp: boas-vindas na hora, lembrete em 24 h e 72 h se parou no meio, parabéns ao ativar; um assunto por mensagem, com link de volta.\n- Defina quem está parado (dias sem uso, cadastro incompleto) e reaja com lembrete, retomada de onde parou ou contato humano nos de maior valor.\n- Meça taxa e tempo de ativação e retenção nos dias 1, 7 e 30; ataque a etapa com maior queda." },
  { id: "churn-prevention", titulo: "Prevenção de cancelamentos", fonte: "coreyhaines31/marketingskills", caminho: "skills/churn-prevention/SKILL.md",
    resumo: "- Separe as perdas: por decisão do cliente e por pagamento que falhou (cartão recusado, boleto ou Pix não pago), esta em geral a mais fácil de recuperar.\n- Fluxo: pedido, motivo, oferta conforme o motivo, confirmação com a data de fim do acesso e caminho fácil para voltar.\n- Pesquisa de saída: uma pergunta, 5 a 8 motivos com campo livre, os mais comuns primeiro, sem tom de culpa.\n- Combine oferta e motivo: caro → desconto de 20% a 30% por 2 ou 3 meses ou plano menor; pouco uso → pausa de 1 a 3 meses ou ajuda para começar; falta recurso → previsão ou alternativa; problema técnico → suporte na hora; negócio fechou → nada.\n- Uma oferta principal e uma reserva, com a economia em reais; botão de continuar cancelando sempre visível.\n- Evite desconto acima de 50% (ensina a ameaçar cancelar), pausa longa, oferta igual para todos e cancelamento escondido.\n- Sinais de risco: uso em queda forte, recurso principal abandonado, reclamações que cessam, visitas à página de pagamento, nota de 0 a 6 ao recomendar.\n- Nota de saúde (0 a 100): soma(peso × nota) ÷ soma dos pesos observados, com todos os sinais na mesma escala, dado ausente fora da conta e cobertura informada; valide com cancelamentos reais.\n- Pagamento: avise antes do vencimento e da validade do cartão; nova tentativa só em recusa temporária, em 1, 3, 5 e 7 dias; lembretes por e-mail ou WhatsApp com link direto para pagar e sem culpar.\n- Métricas: cancelados no mês ÷ clientes no início do mês; salvos ÷ pedidos de cancelamento; veja se o salvo continua após 30 dias; segmente por canal, plano, tempo de casa e motivo." },
  { id: "competitor-profiling", titulo: "Perfil de concorrentes", fonte: "coreyhaines31/marketingskills", caminho: "skills/competitor-profiling/SKILL.md",
    resumo: "- Defina antes: quais concorrentes, o que sua empresa oferece, profundidade (leitura rápida ou perfil completo) e foco (preço, posicionamento, busca).\n- Separe três camadas: observado (com fonte e data), deduzido (rotulado, com grau de confiança) e implicação para você (como pergunta ou opção, não conclusão).\n- Não ver não é não ter: escreva “não encontrado nas páginas vistas em [data]” e confirme antes de usar em anúncio ou comparação pública. Sem preço público não é grátis nem caro.\n- Registre o que mudou, nunca o motivo, a menos que o concorrente o tenha dito em público.\n- Todos os perfis no mesmo modelo: resumo, posicionamento, produtos, preços e condições, clientes e provas, avaliações (nota, quantidade, elogios e queixas), presença na busca, forças e fraquezas com evidência, implicações.\n- Fontes: página inicial, preços, produtos, sobre, clientes, novidades, perfil no Google, Instagram e sites de avaliação.\n- Confronte alegações com sinais visíveis (quem diz ter “10 mil clientes” tem avaliações e tráfego compatíveis?).\n- Seja honesto: não exagere fraquezas nem esconda forças do outro; suas vantagens só valem com prova de clientes, senão são hipóteses.\n- Cada perfil é uma foto com data; “não mudou” só se afirma comparando registros antigos. Ao atualizar, olhe preços primeiro e anote as mudanças.\n- Com muitos concorrentes, comece pelos 5 mais próximos; no fim, resumo com tabela comparativa, mapa de posicionamento (simples ou completo, barato ou premium), 3 a 5 conclusões e lacunas.\n- Número que não se consegue obter fica como indisponível, nunca estimado." },
  { id: "marketing-plan", titulo: "Plano de marketing de 12 meses", fonte: "coreyhaines31/marketingskills", caminho: "skills/marketing-plan/SKILL.md",
    resumo: "- Funil AARRR: aquisição, ativação (primeira boa experiência), retenção, indicação e receita; toda ação diz sua etapa; marca e conteúdo servem a todas.\n- Marketing como investimento: ativos que acumulam (conteúdo para busca, lista de e-mail ou WhatsApp, comunidade, indicação) em vez de picos; muitas apostas pequenas, nenhuma bala de prata; cada material rende em vários canais.\n- Esperança não é estratégia: cada ação diz seu mecanismo, o indicador antecipado e o critério para encerrar se falhar.\n- Filtro do mercado: tamanho × frequência do problema; grande e frequente é o melhor quadrante. Para dimensionar o mercado (TAM/SAM/SOM), cruze métodos (de baixo para cima, buscas, concorrentes, canais) e use faixas.\n- Verba por meta: [(nova receita anual ÷ (receita média por cliente × 12)) × custo de aquisição] ÷ retenção anual, + 10% a 20% para experimentos; esforço em 70/20/10 (o que funciona, próximo canal, testes).\n- Custo de aquisição com salários, conteúdo, ferramentas e terceiros, não só anúncios; se desconhecido, é a principal decisão em aberto.\n- Use dados reais: verba mensal por linha, quem faz o quê, canais atuais e resultados, trabalhos já feitos (reconheça-os), ticket médio e retenção.\n- Roteiro de 90 dias com responsáveis: semanas 1–2 destravar, 3–4 base, 5–8 ritmo, 9–12 acumular; depois metas por trimestre.\n- Bons sinais: resumo legível em 60 segundos, ideias descartadas com motivo, decisões abertas explícitas. Falhas: táticas sem ordem, frases genéricas (“melhorar o SEO”), prometer execução ou verba que não existem, esconder números ruins." },
  { id: "cold-email", titulo: "Abordagem fria por e-mail e mensagem", fonte: "coreyhaines31/marketingskills", caminho: "skills/cold-email/SKILL.md",
    resumo: "Antes de escrever, saiba para quem (cargo, empresa, por que essa pessoa), o que quer, que problema resolve, qual prova tem e qual sinal recente justifica o contato (nova filial, vaga aberta, postagem); tom de colega atento, não de vendedor: frases curtas, linguagem falada, ler em voz alta, e frase que não aproxima a resposta sai; teste da personalização: se tirar a abertura personalizada e a mensagem continuar fazendo sentido, ela é enfeite; fale mais do cliente que de você e não abra apresentando a empresa; um único pedido de baixo esforço (“faz sentido?”), nunca reunião longa no primeiro contato; estruturas: Observação → Problema → Prova → Pedido; Pergunta → Valor → Pedido; Gatilho → Percepção → Pedido; assunto de 2 a 4 palavras, com cara de conversa interna, sem urgência, emoji ou falso “Re:”; sequência de 3 a 5 toques com intervalos crescentes, cada um com ângulo ou prova nova e compreensível sozinho, sem “só passando para lembrar”, e a despedida encerra de fato; e-mail: domínio secundário autenticado e aquecido, lista verificada (rejeição abaixo de 2%), texto simples, no máximo um link, saída fácil da lista, medir respostas e não aberturas; WhatsApp e redes: mesma brevidade, número comercial, horário comercial, sem disparo em massa; resposta em qualquer canal interrompe todos os outros; classifique respostas (interesse, dúvida, objeção, agora não, indicação, descadastro) e responda interessados em minutos com dois horários; evite clichês, jargão, lista de recursos, marcas de texto de IA (“não é X, é Y”) e modelo idêntico trocando só o nome." },
  { id: "prospecting", titulo: "Prospecção e qualificação de clientes", fonte: "coreyhaines31/marketingskills", caminho: "skills/prospecting/SKILL.md",
    resumo: "Cinco fases: definir o perfil de cliente ideal (setor, porte, região, quem decide, sinal de compra que explica o “por que agora” e critérios de descarte) em um parágrafo mais um checklist passa/não passa, e só então buscar; montar uma lista de candidatos 2 a 3 vezes maior que a meta; qualificar cada um com evidência (fonte e data); pontuar; entregar a planilha; escolha uma frente: empresas que vendem para empresas, comércio local (lojas, clínicas, salões) ou caça aos primeiros clientes por sinais públicos de dor (reclamações, avaliações, vagas); no comércio local, pesquise no Google Maps, Instagram, site e diretórios e confira se o negócio está ativo, como está a presença on-line, a distância e o acesso ao dono; confiança alta só com duas fontes independentes ou página oficial, e registre as dúvidas; classificação Quente (perfil + sinal claro + decisor acessível + contato verificado), Morno, Frio e Descartar, mirando uns 20% quentes e 30% mornos; perfil sem sinal nunca é quente; pesquisa individual só para as 25 a 50 melhores contas; verifique e-mail e telefone antes de usar e de novo se a lista envelheceu; 25 contatos bons valem mais que 250 ruins; remova duplicados; entregue tabela com nota, empresa, contato, motivo, fontes, confiança e data, mais os 3 a 5 alvos prioritários com o porquê e as pendências; limites: nada de raspagem em massa, burla de captcha ou login, dados vazados ou listas sem origem; só canais comerciais públicos; não segmentar por saúde, religião, política, sexualidade ou aperto financeiro; guardar origem e data de cada contato." },
  { id: "sales-enablement", titulo: "Materiais de apoio a vendas", fonte: "coreyhaines31/marketingskills", caminho: "skills/sales-enablement/SKILL.md",
    resumo: "Material bom é o que o vendedor usa: construa com quem vende, na linguagem dele; se reescrevem antes de mandar, está errado; adapte a quem compra, à etapa e ao uso; a resposta tem de ser achada em segundos, no meio da ligação ou da conversa no WhatsApp; toda afirmação vira efeito em dinheiro, tempo ou risco; só diga o que dá para defender: vantagem sem evidência (depoimento, gravação) é hipótese, dado de concorrente leva fonte e data, e admita onde o concorrente é melhor; apresentação de umas 11 telas: problema, custo de não agir, mudança no mercado, abordagem, usos reais, provas, um caso, implantação, retorno, preço e próximo passo, uma ideia por tela; folha única: problema, solução, 3 diferenciais, uma prova e contato com nome; objeções (preço, momento, concorrente, quem decide, “está bom assim”): registre a frase exata, a preocupação real, a resposta, a prova e uma pergunta para seguir; na objeção ao vivo, entenda quem disse e em que etapa, dê uma resposta pronta para falar, use só prova real (nunca invente número) e saiba quando não insistir; cartão por concorrente com onde ele é forte, onde ganhamos e para quem, quando desistir e data da última checagem; análise de ganhos e perdas: inclua as vitórias, separe por segmento antes de contar, um motivo principal por negócio com citação e fonte, e informe o tamanho da amostra (menos de 5 casos é só sinal); calculadora de retorno: dados do cliente → economia → prazo para se pagar; demonstração só depois de entender a dor; proposta curta com preço visível; manual de vendas com dono e revisão periódica." },
  { id: "revops", titulo: "Operação de receita e funil comercial", fonte: "coreyhaines31/marketingskills", caminho: "skills/revops/SKILL.md",
    resumo: "Uma fonte única de verdade para contatos e negócios (sistema de clientes ou planilha mestre); defina etapas, pontuação e regras no papel antes de automatizar, porque automatizar processo ruim só acelera o erro; cada passagem de bastão entre marketing, vendas e pós-venda tem prazo, registro e responsável, com definições combinadas; etapas com critério de entrada, saída e dono: contato → qualificado pelo marketing (exige perfil e interesse, os dois) → aceito por vendas → oportunidade → cliente → promotor; prazo típico: primeiro contato em até 4 horas úteis e decisão em 48 horas, devolvendo com motivo; a pontuação soma perfil (quem é), comportamento (pediu orçamento, viu preços) e pontos negativos (concorrente, estudante, descadastro), é validada no histórico de ganhos e perdas usando só o que se sabia na hora e recalibrada por trimestre; erros: supervalorizar quem baixou material, não ter pontos negativos, tratar toda visita igual; distribuição com a regra mais específica primeiro e sempre um responsável reserva; velocidade de resposta é o que mais pesa: minutos, não horas, com alerta e escalonamento; no funil, campos obrigatórios por etapa, alerta para negócio parado além do dobro da média ou que pulou etapa, e adiamento só com motivo; métricas: conversão e tempo por etapa, velocidade do funil = (nº de negócios × ticket médio × taxa de ganho) ÷ ciclo médio, cobertura de 3 a 4 vezes a meta, ganho por origem, valor do cliente acima de 3 vezes o custo de aquisição; descontos com alçadas de aprovação e exceções registradas (a mais pedida vira regra)." },
  { id: "offers", titulo: "Construção de ofertas", fonte: "coreyhaines31/marketingskills", caminho: "skills/offers/SKILL.md",
    resumo: "A oferta vem antes do texto: anúncio melhor em oferta fraca rende pouco, e muito pedido de “melhorar o texto” é, na verdade, de melhorar a oferta; Equação de Valor (Hormozi): Valor = (Resultado desejado × Probabilidade percebida de conseguir) ÷ (Tempo até o resultado × Esforço e sacrifício); suba o numerador com resultado concreto e nomeado, provas, garantia e método claro; reduza o denominador com início rápido, primeira vitória cedo, serviço feito no lugar do cliente e menos decisões; querer baixar o preço quase sempre indica alavanca fraca, porque preço é comparação, não valor; oferta completa tem seis partes: entrega principal, bônus que valorizam o principal, garantia, motivo real para agir agora, nome e preço com forma de pagamento (parcelamento, condição no Pix); diagnóstico: identifique o tipo de negócio (serviço, curso, mentoria, produto digital), escreva a oferta atual em linguagem simples, dê nota de 1 a 10 a cada alavanca e trate a mais baixa como gargalo, mexa em um componente por vez e projete ganho honesto de 10 a 40% por mudança, multiplicando e não somando (1,2 × 1,3 = 1,56), confirmando com teste; evite escassez falsa (cronômetro que reinicia, últimas vagas inventadas), garantia exagerada, bônus com valor inflado, estética de “método secreto” e desconto para conquistar cliente novo, que atrai quem mais cancela e ancora o produto como barato (desconto só para cliente atual ou data sazonal real); troque superlativos (revolucionário, segredo, 100% garantido sem condições) por números, clientes reais, resultados e prazos concretos." },
  { id: "pricing", titulo: "Precificação e pacotes", fonte: "coreyhaines31/marketingskills", caminho: "skills/pricing/SKILL.md",
    resumo: "Preço tem três eixos: o que entra em cada plano ou pacote, a métrica de cobrança (por pessoa, por uso, por item, valor fixo) e o valor em si; cobre pelo valor, entre a próxima melhor alternativa do cliente (piso) e o valor percebido (teto); custo é só limite mínimo e preço do concorrente é referência, não meta; o primeiro preço é uma aposta para aprender: escolha a faixa pelo tipo de cliente, lance e observe; evite preço baixíssimo para tirar atrito: gera tração falsa, atrai quem mais cancela e dificulta subir depois; boa métrica de cobrança cresce com o benefício do cliente, é fácil de entender e difícil de burlar (quanto mais usa, mais ganha?); Bom–Melhor–Ótimo: entrada, intermediário recomendado como âncora e completo a 2 ou 3 vezes o intermediário; pesquisa: Van Westendorp (caro demais, barato a ponto de desconfiar, caro mas consideraria, pechincha) dá faixa aceitável, não prova de receita; MaxDiff (mais e menos importante) ajuda a montar pacotes; sinais para subir: ninguém estranha o preço, comentários de que está barato, conversão e retenção muito altas, muito valor novo; ao subir, teste primeiro com clientes novos, mantenha o preço antigo só como transição, migre 5 a 10% da base e amplie em ondas observando cancelamentos, avise com meses de antecedência explicando o motivo e oferecendo saída generosa (travar o preço no plano anual, crédito); alguma perda é esperada e costuma vir dos menos lucrativos; página de preços com opção recomendada em destaque, desconto anual de 17 a 20%, para quem é cada opção e preço escrito, não só “fale conosco”." },
  { id: "systematic-debugging", titulo: "Depuração sistemática", fonte: "obra/superpowers", caminho: "skills/systematic-debugging/SKILL.md",
    resumo: "Regra central: nenhuma correção antes de achar a causa raiz; remendar sintoma é falha, inclusive sob pressa; Fase 1, investigar: ler a mensagem de erro e o rastro inteiros, reproduzir de forma confiável (se não reproduz, colete mais dados em vez de chutar), checar o que mudou (commits, dependências, configuração, ambiente), em sistemas de várias camadas registrar o que entra e sai em cada fronteira e rodar uma vez para ver onde quebra, e rastrear o valor errado para trás até a origem, corrigindo lá; Fase 2, padrão: achar código parecido que funciona, ler a referência completa e listar todas as diferenças, mesmo as que parecem irrelevantes; Fase 3, hipótese: uma de cada vez, escrita (“acho que X causa isso porque Y”), testada com a menor mudança possível e uma variável por vez; se falhar, nova hipótese em vez de empilhar correções; admitir quando não entende; Fase 4, correção: primeiro um teste que falha reproduzindo o defeito, depois uma única mudança na causa, sem melhorias de carona, e confirmar que o teste passa e nada mais quebrou; regra das três tentativas: se três correções falharam ou cada uma revela problema novo em outro lugar, pare e discuta a arquitetura com o responsável antes da quarta; sinais de alerta: “conserto agora, investigo depois”, mudar algo para ver no que dá, várias mudanças de uma vez; se a causa for mesmo externa, documente o investigado, trate (nova tentativa, tempo limite) e monitore, mas quase todo caso “sem causa” é investigação incompleta; depois da causa, valide em várias camadas; espere por condição, não por tempo fixo." },
  { id: "requesting-code-review", titulo: "Pedido de revisão de código", fonte: "obra/superpowers", caminho: "skills/requesting-code-review/SKILL.md",
    resumo: "Revise cedo e com frequência: obrigatório ao fim de cada tarefa ou funcionalidade grande e antes de integrar; o revisor não pode ser quem fez o trabalho e recebe contexto preparado: o que foi feito, os requisitos ou o plano e o intervalo exato de mudanças, sem o histórico de raciocínio de quem implementou; a revisão só lê e não altera o repositório; o que checar: aderência ao plano (desvios justificados, itens faltando), qualidade (separação de responsabilidades, tratamento de erros, tipos, duplicação sem abstração precoce, casos-limite), arquitetura (desempenho, segurança, encaixe no código vizinho), testes (comportamento real, não simulações; casos-limite) e prontidão para produção (migração de esquema, compatibilidade, documentação); silêncio da especificação não é permissão: o que uma pessoa razoável esperaria também é requisito, e o revisor lista o que deixou de julgar e por quê; classifique pela gravidade real: Crítico (defeito, segurança, perda de dados, quebra), Importante (arquitetura, funcionalidade faltando, erro mal tratado, lacuna de teste) e Menor (estilo, otimização, documentação); cada item com arquivo e linha, o que está errado, por que importa e como corrigir; reconheça acertos com precisão e termine com veredito claro: pronto, não pronto ou pronto com correções; quem recebe corrige o crítico na hora, o importante antes de seguir e anota o menor, e discorda com argumento técnico e prova (código, teste) quando o revisor errar; erros comuns: pular revisão por ser simples, aprovar sem ler, tratar detalhe como crítico, comentário vago." },
  { id: "test-driven-development", titulo: "Desenvolvimento guiado por testes", fonte: "obra/superpowers", caminho: "skills/test-driven-development/SKILL.md",
    resumo: "Regra central: nenhum código de produção sem antes um teste que falhou; código escrito antes do teste é descartado e refeito a partir do teste, sem guardar “de referência”; ciclo Vermelho–Verde–Refatorar: escreva um teste mínimo para um comportamento, rode e veja falhar pelo motivo certo (falta da funcionalidade, não erro de digitação; se passou de primeira, está testando algo que já existe), escreva o código mais simples que passa, rode e veja passar junto com o resto, e só então limpe nomes, duplicação e auxiliares sem mudar comportamento; verde é a suíte inteira do projeto, não só o arquivo novo, e toda falha vista, mesmo alheia, entra no relatório; bom teste cobre uma coisa só (se o nome tem “e”, divida), tem nome que descreve o comportamento, usa código real e só simula dependência quando inevitável, verifica o comportamento e não a simulação, e você sabe que mudança no código o faria falhar; não construa o que o teste não pede (YAGNI); teste escrito depois prova pouco: passa de cara, fica enviesado pelo código e cobre só o que você lembrou; dificuldade de testar é sinal de design: teste complicado indica interface complicada e precisar simular tudo indica acoplamento (injete dependências); defeito encontrado começa por um teste que o reproduz, o que também impede a volta do erro; exceções só com aval do responsável: protótipo descartável, código gerado e configuração; checklist: toda função nova tem teste, cada teste foi visto falhando pelo motivo esperado, código mínimo, tudo passa, saída limpa sem avisos, casos-limite e erros cobertos." },
  { id: "verification-before-completion", titulo: "Verificação antes de concluir", fonte: "obra/superpowers", caminho: "skills/verification-before-completion/SKILL.md",
    resumo: "Regra central: nenhuma afirmação de pronto, corrigido ou passando sem evidência nova, obtida agora; portão em cinco passos: identificar qual comando ou checagem prova a afirmação, executá-lo completo e do zero, ler a saída inteira com código de saída e contagem de falhas, conferir se ela confirma o que se quer dizer e só então afirmar citando a evidência, ou relatar o estado real; o que vale como prova: testes passando exigem saída com zero falhas, não execução antiga nem “deve passar”; verificador de estilo limpo não prova que compila; build aprovado exige o comando de build terminando sem erro; defeito corrigido exige testar o sintoma original, não apenas ter mudado o código; teste de regressão exige o ciclo completo: passa, desfaz a correção e ele precisa falhar, restaura e passa de novo; trabalho delegado só conta depois de conferir as mudanças reais no controle de versão, nunca pelo relato de quem fez; requisitos atendidos exigem reler o plano e checar item por item, porque testes verdes não bastam; sinais de alerta: usar “deve”, “provavelmente” ou “parece”; comemorar antes de verificar; ir fazer commit, publicar ou abrir pedido de integração sem checar; confiar em relatório de terceiros; verificação parcial; cansaço e vontade de encerrar; a regra vale para qualquer forma de dizer que deu certo, inclusive sinônimos e insinuações, e também antes de passar à próxima tarefa ou de delegar; confiança não é evidência e verificação parcial não prova nada." },
  { id: "supabase-postgres-best-practices", titulo: "Boas práticas de Postgres", fonte: "supabase/agent-skills", caminho: "skills/supabase-postgres-best-practices/SKILL.md",
    resumo: "Prioridade: consultas, conexões e segurança primeiro; índices: indexe colunas de filtro e junção; chave estrangeira não ganha índice automático, crie; índice composto com colunas de igualdade antes das de intervalo; índice parcial quando a consulta sempre filtra igual; INCLUDE para cobrir colunas lidas; tipo certo: B-tree padrão, GIN para JSONB, arrays e busca textual, BRIN para séries temporais grandes; conexões: sempre um pooler, em modo transação, work_mem × conexões até 25% da RAM, tempo limite para sessão ociosa em transação, sem instruções preparadas nomeadas no modo transação; segurança por linha (RLS) ativada e forçada, não só filtro na aplicação; nas políticas, chame a função do usuário atual dentro de um SELECT para avaliar uma vez e indexe as colunas usadas; SECURITY DEFINER só em esquema não exposto, com search_path vazio e EXECUTE revogado de papéis públicos; menor privilégio, nunca superusuário na aplicação; esquema: chave bigint identity (UUID v7 se distribuído; evite UUID v4 em tabela grande), text, timestamptz, boolean, numeric para dinheiro, nomes minúsculos em snake_case; migrações idempotentes (não existe ADD CONSTRAINT IF NOT EXISTS); concorrência: transação curta sem chamada externa dentro, statement_timeout, travar linhas sempre na mesma ordem, filas com FOR UPDATE SKIP LOCKED; acesso: acabe com N+1 (ANY(array) ou JOIN), pagine por cursor e não por OFFSET, insira em lote ou com COPY, use INSERT … ON CONFLICT; diagnostique com EXPLAIN (ANALYZE, BUFFERS) antes de adivinhar e mantenha estatísticas em dia (ANALYZE, autovacuum)." },
];

