const POR_ID: Record<string, Referencia> = Object.fromEntries(REFERENCIAS.map((r) => [r.id, r]));
export function referenciasPara(e: EspecialistaIA, s: SkillEspecialista): Referencia[] {
  return (REFERENCIAS_DA_SKILL[`${e.id}::${s.nome}`] ?? []).map((id) => POR_ID[id]).filter((r): r is Referencia => !!r && !!r.resumo).slice(0, 2);
}
